setup_files.registry.py:
CHANNELS = {}


def register(name, handler):
    """A handler is a callable: handler(recipient, message) -> dict (a
    delivery receipt). Registering the same name twice replaces it."""
    CHANNELS[name] = handler


def handler_for(name):
    if name not in CHANNELS:
        raise KeyError(f"no channel registered: {name}")
    return CHANNELS[name]

