from registry import register


def send_email(recipient, message):
    return {"channel": "email", "to": recipient, "status": "sent", "body": message}


def send_sms(recipient, message):
    if len(message) > 160:
        raise ValueError("sms body exceeds 160 characters")
    return {"channel": "sms", "to": recipient, "status": "sent", "body": message}


register("email", send_email)
register("sms", send_sms)

setup_files.dispatcher.py:
from registry import handler_for


def dispatch(channel, recipient, message):
    """Look up the channel and deliver; raises KeyError for an unknown
    channel (from handler_for) and propagates any handler error."""
    handler = handler_for(channel)
    return handler(recipient, message)


def dispatch_all(channel, recipients, message):
    """Deliver to every recipient; returns the list of receipts IN ORDER.
    Stops and propagates on the first failure (no partial-success handling)."""
    return [dispatch(channel, r, message) for r in recipients]

test_setup_files.test_webhook_hidden.py:
import pytest

import channels  # noqa: F401  (registers email/sms/webhook as an import side effect)
from dispatcher import dispatch, dispatch_all


def test_webhook_dispatch_success():
    receipt = dispatch("webhook", "https://hooks.example.com/1", "ping")
    assert receipt == {
        "channel": "webhook", "to": "https://hooks.example.com/1",
        "status": "sent", "body": "ping",
    }


def test_webhook_rejects_non_url_recipient():
    with pytest.raises(ValueError):
        dispatch("webhook", "not-a-url", "ping")


def test_webhook_works_in_dispatch_all():
    urls = ["https://a.example.com", "https://b.example.com"]
    receipts = dispatch_all("webhook", urls, "batch")
    assert [r["to"] for r in receipts] == urls


def test_existing_channels_unaffected():
    assert dispatch("email", "a@x.io", "hi")["channel"] == "email"
    assert dispatch("sms", "+1", "hi")["channel"] == "sms"

